```
private int checkMirrorAndBalance(TreeNode a, TreeNode b) {
    if (a == null && b == null) return 0;
    if (a == null || b == null || a.val != b.val) return -1;

    int hOuter = checkMirrorAndBalance(a.left, b.right);
    if (hOuter == -1) return -1;

    int hInner = checkMirrorAndBalance(a.right, b.left);
    if (hInner == -1) return -1;

    if (Math.abs(hOuter - hInner) > 1) return -1;

    return 1 + Math.max(hOuter, hInner);
}
```
