```
private int checkMirrorAndBalance(TreeNode left, TreeNode right) {
    if (left == null && right == null) return 0;
    if (left == null || right == null) return -1;
    if (left.val != right.val) return -1;

    int leftHeight = checkMirrorAndBalance(left.left, right.right);
    if (leftHeight == -1) return -1;

    int rightHeight = checkMirrorAndBalance(left.right, right.left);
    if (rightHeight == -1) return -1;

    if (Math.abs(leftHeight - rightHeight) > 1) return -1;

    return 1 + Math.max(leftHeight, rightHeight);
}
```
