Let's write exact code:

```
public boolean isBalancedAndSymmetric(TreeNode root) {
    if (root == null) {
        return true;
    }

    // The two subtrees must be mirror images.  A successful helper call
    // also proves that every descendant is balanced.
    return checkMirrorAndBalance(root.left, root.right) != -1;
}

private int checkMirrorAndBalance(TreeNode a, TreeNode b) {
    if (a == null &amp;&amp; b == null) {
        return 0;
    }
    if (a == null || b == null) {
        return -1;
    }
    if (a.val != b.val) {
        return -1;
    }

    int h1 = checkMirrorAndBalance(a.left, b.right);
    if (h1 == -1) {
        return -1;
    }

    int h2 = checkMirrorAndBalance(a.right, b.left);
    if (h2 == -1) {
        return -1;
    }

    // For a, child heights are h1 and h2.
    // For b, they are h2 and h1, so this checks both nodes.
    if (Math.abs(h1 - h2) > 1) {
        return -1;
    }

    return 1 + Math.max(h1, h2);
}
```

