public final class IslandFinder {
    private IslandFinder() {
    }

    /**
     * Returns the number of cells in the largest 4-connected island.
     * The input map is not changed.
     */
    public static int findLargestIsland(boolean[][] map) {
        if (map == null || map.length == 0) {
            return 0;
        }

        if (map[0] == null) {
            throw new IllegalArgumentException("map rows must not be null");
        }

        int rows = map.length;
        int cols = map[0].length;

        // Java permits jagged arrays; require a rectangular map.
        for (int r = 0; r < rows; r++) {
            if (map[r] == null || map[r].length != cols) {
                throw new IllegalArgumentException("map must be rectangular");
            }
        }

        if (cols == 0) {
            return 0;
        }

        boolean[][] visited = new boolean[rows][cols];
        int largest = 0;

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (map[r][c] && !visited[r][c]) {
                    int islandSize = exploreLand(
                            map, visited, r, c, rows, cols);
                    largest = Math.max(largest, islandSize);
                }
            }
        }

        return largest;
    }

    private static int exploreLand(boolean[][] map,
                                   boolean[][] visited,
                                   int row, int col,
