public static int numOccurrences(String string, String word) {
    if (word == null || word.isEmpty()) {
       throw new IllegalArgumentException("word must be nonempty");
    }
    int total = 0;
    String current = string;

    while (true) {
        StringBuilder next = new StringBuilder(current.length());
        int layerCount = 0;
        int i = 0;
        while (i < current.length()) {
            if (current.startsWith(word, i)) {
                layerCount++;
                i += word.length();
            } else {
                next.append(current.charAt(i));
                i++;
            }
        }
        if (layerCount == 0) return total;
        total += layerCount;
        current = next.toString();
    }
}
