public static int numNestedOccurrences(String string, String word) {
    if (word == null || word.isEmpty()) {
        throw new IllegalArgumentException("word must not be empty");
    }
    int total=0;
    String current=string;
    while (true) {
       StringBuilder remaining = new StringBuilder(current.length());
       int foundThisLayer=0;
       for (int i=0; i&lt;current.length();) {
          if (current.startsWith(word,i)) {
             foundThisLayer++;
             i += word.length();
          } else {
             remaining.append(current.charAt(i));
             i++;
          }
       }
       if(foundThisLayer==0) return total;
       total += foundThisLayer;
       current=remaining.toString();
    }
}
