public boolean isTraversable(int[][] mountain) {
    if(mountain.length == 0 || mountain[0].length == 0) {
        return true;
    }

    int currentRow = 0;
    int currentCol = 0;

    while(currentRow != mountain.length - 1 && currentCol != mountain.length - 1) {
        boolean foundTrail = false;

        // Move 1: Upward
        if(currentRow + 1 &lt; mountain.length &amp;&amp; mountain[currentRow + 1][currentCol] == 1) {
            currentRow += 1;
            foundTrail = true;
        }

        // Move 2: Downward
        else if(currentRow - 1 &gt;= 0 &amp;&amp; mountain[currentRow - 1][currentCol] == 1) {
            currentRow -= 1;
            foundTrail = true;
        }

        // Move 3: Rightward
        else if(currentCol &lt; mountain[0].length &amp;&amp; mountain[currentRow][currentCol + 1] == 1) {
            currentCol += 1;
            foundTrail = true;
        }

        // Move 4: Leftward
        else if(currentCol - 1 &gt; 0 &amp;&amp; mountain[currentRow][currentCol - 1] == 1) {
            currentCol -= 1;
            foundTrail = true;
        }

        if(!foundTrail) {
            return false;
        }
    }
    return true;
}
