```
public boolean isTraversable(int[][] mountain) {
    if (mountain == null || mountain.length == 0 || mountain[0].length == 0) {
        return false;
    }
    int rows = mountain.length;
    int cols = mountain[0].length;
    if (mountain[0][0] != 1 || mountain[rows - 1][cols - 1] != 1) {
        return false;
    }

    boolean[][] seen = new boolean[rows][cols];
    Deque<int[]> queue = new ArrayDeque<>();
    queue.add(new int[]{0, 0});
    seen[0][0] = true;
    int[][] directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    while (!queue.isEmpty()) {
        int[] p = queue.poll();
        int r = p[0], c = p[1];
        if (r == rows - 1 && c == cols - 1) {
            return true;
        }
        for (int[] d : directions) {
            int nr = r + d[0];
            int nc = c + d[1];
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols
                    && !seen[nr][nc] && mountain[nr][nc] == 1) {
                seen[nr][nc] = true;
                queue.add(new int[]{nr, nc});
            }
        }
    }
    return false;
}
```
